ga14(){return"Suggested dates"},
ga16(){return"Use this date"},
gaxc(){return"No conflicts detected"},
gaxe(){return"Choose up to 90 days starting today or later."},
ga13(){return"Could not load availability. Try again."},
gaxb(){return"The group or permissions changed. Refresh the calendar and try again."},
axd(a,b){return a+" \u2013 "+b},
axf(a,b){return""+a+" of "+b},
ax5(a){var s=null
return A.eK(a,s,this.a,s,"1 busy",""+a+" busy",s,s)},
